cat >> tests/tasks.test.ts <<'EOF'

async function deleteTask(server: Running, id: string | number): Promise<Response> {
  return fetch(`${server.baseUrl}/api/tasks/${id}`, { method: "DELETE" });
}

describe("SL-006 delete a task", () => {
  describe("the API", () => {
    let server: Running;

    before(async () => {
      server = await startServer();
    });
    after(async () => {
      await server?.stop();
    });

    it("answers 204 and removes only that task from the list", async () => {
      const { task: keep } = (await (await createTask(server, "Keep")).json()) as { task: Task };
      const { task: drop } = (await (await createTask(server, "Drop")).json()) as { task: Task };

      const response = await deleteTask(server, drop.id);
      assert.equal(response.status, 204);
      assert.equal(await response.text(), "");

      assert.deepEqual(
        (await listTasks(server)).map((t) => t.id),
        [keep.id],
      );
    });

    it("answers 404 not_found for a task that does not exist or was already deleted", async () => {
      const { task } = (await (await createTask(server, "Once")).json()) as { task: Task };
      assert.equal((await deleteTask(server, task.id)).status, 204);

      for (const id of [task.id, 999999, "abc", "1.5", "-1"]) {
        const response = await deleteTask(server, id);
        assert.equal(response.status, 404, `id ${id}`);
        const body = (await response.json()) as { error: { code: string } };
        assert.equal(body.error.code, "not_found");
      }
    });
  });

  describe("the page", () => {
    it("has a delete button per task that asks for confirmation before calling DELETE", async () => {
      const server = await startServer();
      try {
        const script = await (await fetch(`${server.baseUrl}/app.js`)).text();
        assert.match(script, /confirm\(/);
        assert.match(script, /method:\s*["']DELETE["']/);
        assert.doesNotMatch(script, /innerHTML/);
      } finally {
        await server.stop();
      }
    });
  });

  describe("durability", () => {
    it("a deleted task stays deleted after kill -9 and a restart", async () => {
      const dbPath = newDbPath();
      let server = await startServer(dbPath);
      try {
        const { task } = (await (await createTask(server, "Gone")).json()) as { task: Task };
        assert.equal((await deleteTask(server, task.id)).status, 204);

        await server.stop();
        server = await startServer(dbPath);
        assert.deepEqual(await listTasks(server), []);
      } finally {
        await server.stop();
      }
    });
  });
});
